+// API keys, roles and the audit log. Keys live in `apiKeys` as
+// { key, name, role }; audit entries in `audit` (docs/DATA.md).
+import { createHash, timingSafeEqual } from "node:crypto";
+
+/** What each role may do: "read" (GET), "cook" (kitchen work), "manage" (everything). */
+export const ROLES = Object.freeze({
+  viewer: Object.freeze(["read"]),
+  cook: Object.freeze(["read", "cook"]),
+  manager: Object.freeze(["read", "cook", "manage"]),
+});
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for a secret, or null when there is none. */
+export function findKey(store, secret) {
+  if (typeof secret !== "string" || !secret) return null;
+  const wanted = digest(secret);
+  return (store.data.apiKeys ?? []).find((k) => k.role in ROLES && timingSafeEqual(digest(k.key), wanted)) ?? null;
+}
+
+/** Whether `role` may perform `action` ("read", "cook" or "manage"). */
+export function allows(role, action) {
+  return (ROLES[role] ?? []).includes(action);
+}
+
+/** Appends an audit entry { at, key, method, path, status }; returns it. */
+export function recordAudit(store, { key, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, key, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.id - a.id);
+}
