@@ -0,0 +1,63 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, KEYS } from "./helpers.js";
+
+test("requests without a key or with an unknown key are 401", async () => {
+  const { raw } = app();
+  const none = await raw({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const bad = await raw({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(bad.status, 401);
+  const unknownRoute = await raw({ path: "/nope" });
+  assert.equal(unknownRoute.status, 401);
+});
+
+test("the Authorization header is matched case-insensitively", async () => {
+  const { raw } = app();
+  const res = await raw({ path: "/items", headers: { Authorization: `bearer ${KEYS.viewer}` } });
+  assert.equal(res.status, 200);
+});
+
+test("viewers may only read", async () => {
+  const { handle, store } = app(undefined, { key: KEYS.viewer });
+  assert.equal((await handle({ path: "/items" })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const cook = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(cook.status, 403);
+  assert.equal(cook.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("cooks may cook, waste, log temperatures and count, but not manage", async () => {
+  const manager = app();
+  const { handle } = app(manager.store, { key: KEYS.cook });
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", body: { qty: 1, reason: "dropped" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).status, 403);
+  const take = (await manager.handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 6, counted: 12 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [] } })).status, 403);
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("changes are audited, newest first, for managers only", async () => {
+  const { handle, store } = app();
+  const cook = app(store, { key: KEYS.cook });
+  await cook.handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await cook.handle({ method: "POST", path: "/jobs/nightly" });
+  await handle({ path: "/items" });
+  const res = await handle({ path: "/audit" });
+  assert.equal(res.status, 200);
+  assert.deepEqual(
+    res.body.map(({ key, method, path, status }) => ({ key, method, path, status })),
+    [
+      { key: "seed cook", method: "POST", path: "/jobs/nightly", status: 403 },
+      { key: "seed cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+    ],
+  );
+  assert.equal(res.body[0].at, "2026-10-28T10:00:00.000Z");
+  assert.equal(JSON.stringify(res.body).includes("seed-cook-key"), false);
+});
